#include <WiFi.h>

// Пин кнопки
const int buttonPin = 4;

// Флаг состояния глушилки
bool isJamming = false;

void setup() {
  Serial.begin(115200);

  // Настройка пина кнопки (внутренний подтягивающий резистор)
  pinMode(buttonPin, INPUT_PULLUP);

  // Начальное состояние: Wi-Fi выключен
  WiFi.mode(WIFI_OFF);

  Serial.println("ESP32-S3 Wi-Fi Jammer Ready");
  Serial.println("Нажмите кнопку на GPIO 4 для включения/выключения глушилки");
}

void loop() {
  // Чтение состояния кнопки
  if (digitalRead(buttonPin) == LOW) {
    delay(200); // Антидребезг

    // Переключаем состояние
    isJamming = !isJamming;

    if (isJamming) {
      startJamming();
    } else {
      stopJamming();
    }

    // Ждем, пока кнопка не будет отпущена
    while (digitalRead(buttonPin) == LOW) {
      delay(10);
    }
  }

  // Если включен режим глушения, продолжаем генерировать шум
  if (isJamming) {
    jamWifi();
  }
}

void startJamming() {
  Serial.println(">>> WI-FI GULISHILKA VKLUCHENA <<<");

  // Отключаем обычные сервисы Wi-Fi
  WiFi.disconnect(true);
  WiFi.mode(WIFI_OFF);

  // Включаем Wi-Fi в режиме станции для генерации шума
  WiFi.mode(WIFI_STA);
}

void stopJamming() {
  Serial.println("<<< WI-FI GULISHILKA VYKLYUCHENA <<<");
  WiFi.mode(WIFI_OFF);
}

void jamWifi() {
  // Генерация шума Wi-Fi
  // Мы быстро переключаем каналы и отправляем пакеты, создавая помехи

  static uint8_t channel = 1;
  static unsigned long lastSwitch = 0;

  // Переключаем канал каждые 10 мс (очень быстро)
  if (millis() - lastSwitch > 10) {
    lastSwitch = millis();

    // Переключаем канал (1-13 для 2.4 GHz)
    channel++;
    if (channel > 13) channel = 1;

    WiFi.setChannel(channel);

    // Отправляем пустой пакет или сканируем, чтобы создать радиошум
    // Это создает максимальную нагрузку на передатчик
    WiFi.scanNetworks(false); 

    // Увеличиваем мощность передатчика до максимума
    // Примечание: setOutputPower может быть недоступен в некоторых версиях
    // Если есть ошибка, закомментируйте эту строку
    // WiFi.setOutputPower(20.0); 

    // Альтернативный способ увеличения мощности (если доступен)
    WiFi.setTxPower(WIFI_POWER_8dBm);
  }
}
